-- 2026-11-16 每日收录：QWOP、群体的智慧与疯狂、反物质维度、0h h1、睡美人，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('qwop', 'QWOP', 'QWOP', 'qwop paobu aoyun bennettfoddy', 'Bennett Foddy', '', '', NULL, '', 0, 2008, 'action', '["体育","物理","经典"]', 8, 0.1, 'io', 'https://www.foddy.net/legacy/Athletics.html', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '只用 Q、W、O、P 四个键，跑完 100 米', '分别控制大腿和小腿，用四个键让运动员跑完 100 米。比听上去难得多。', 'Control each thigh and calf separately and try to run 100 metres. It is much harder than it sounds.', '由 Bennett Foddy 制作，2008 年起在 foddy.net 公开发布。原页托管在 www.foddy.net，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Bennett Foddy and published on foddy.net since 2008. Hosted at www.foddy.net; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/qwop.jpg', 1280, 800, 'center', '["assets/posters/qwop.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -18, 1794794400000, 'Run 100 metres with just the Q, W, O and P keys.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('wisdom-of-crowds', '群体的智慧与疯狂', 'The Wisdom and/or Madness of Crowds', 'qunti zhihui fengkuang quntidezhihuiyu fengkuang crowds wisdom madness', 'Nicky Case', '', '', NULL, '', 0, 2018, 'story', '["互动叙事","科普","模拟"]', 0, 0.02, 'story', 'https://ncase.me/crowds/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '人与人连上之后，想法会怎样传开', '拖动小人、改连线，看想法、偏见和从众怎样在一张关系网里扩散。原页有简体中文等译本。', 'Drag people and rewire their links to see how ideas, bias and conformity spread through a network. Translations, including Simplified Chinese, are on the page.', '由 Nicky Case 制作，以公共领域（CC0）发布。原页托管在 ncase.me/crowds，不是即玩的作品。在即玩里直接打开原作。页底可切换简体中文等多种语言。开玩不用登录。', 'Made by Nicky Case and released into the public domain under CC0. Hosted at ncase.me/crowds; it is not a Jiwan original. It opens here. Translations, including Simplified Chinese, are linked at the bottom of the page. No account needed.', 'assets/posters/wisdom-of-crowds.jpg', 1280, 800, 'center', '["assets/posters/wisdom-of-crowds.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -17, 1794794400000, 'Once people connect, how do ideas spread?', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('antimatter-dimensions', '反物质维度', 'Antimatter Dimensions', 'fanshizhi weidu fanshizhiweidu antimatter dimensions hevipelle ivark', 'Hevipelle (IvarK)', '', '', NULL, '', 0, 2016, 'idle', '["放置","增量","策略"]', 350, 0.08, 'clicker', 'https://ivark.github.io/AntimatterDimensions/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '买能生产反物质的维度，再一层层重置', '从第一维度开始生产反物质，解锁挑战、无限和更高层级的重度增量放置游戏。', 'A deep incremental game: start with the first dimension, then unlock challenges, Infinity and layers beyond.', '由 Hevipelle（Ivar Kerajärvi）制作，源码以 MIT 许可在 GitHub 发布。原页托管在 ivark.github.io/AntimatterDimensions，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。页内商店为可选内容，不影响免费游玩。', 'Made by Hevipelle (Ivar Kerajärvi); the source is MIT-licensed on GitHub. Hosted at ivark.github.io/AntimatterDimensions; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed. The in-game shop is optional and not required to play.', 'assets/posters/antimatter-dimensions.jpg', 1280, 800, 'center', '["assets/posters/antimatter-dimensions.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -16, 1794794400000, 'Buy dimensions that make antimatter, then prestige layer after layer.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('0h-h1', '0h h1', '0h h1', 'oh hi 0hh1 linghuan luoji takuzu binairo q42 martinkool', 'Martin Kool / Q42', '', '', NULL, '', 0, 2014, 'puzzle', '["益智","逻辑","休闲"]', 230, 0.08, 'story', 'https://0hh1.com/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '红蓝两色，三条规则，把格子填完', '同一行或列不能有三个同色相连，红蓝数量要相等，也没有两行或两列完全相同。从 4×4 玩到 10×10。', 'No three adjacent tiles of the same colour, equal counts in each row and column, and no two rows or columns alike. Boards run from 4×4 to 10×10.', '由 Martin Kool / Q42 制作，源码以 MIT 许可发布。原页托管在 0hh1.com，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Martin Kool / Q42; the source is released under the MIT licence. Hosted at 0hh1.com; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/0h-h1.jpg', 1280, 800, 'center', '["assets/posters/0h-h1.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -15, 1794794400000, 'Two colours, three rules, fill the grid.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sleeping-beauty', '睡美人', 'Sleeping Beauty', 'shuimeiren sleeping beauty roguelike 7drl ondras', 'Ondřej Žára (ondras)', '', '', NULL, '', 0, 2017, 'story', '["肉鸽","ASCII","冒险"]', 50, 0.08, 'story', 'https://ondras.github.io/sleeping-beauty/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '走进荆棘塔，去叫醒沉睡的公主', '一款咖啡时间就能打完的网页 Roguelike：探索、战斗，在永久死亡和随机地图里接近睡美人。', 'A coffee-break roguelike: explore, fight, and approach the sleeping princess on a permadeath, procedurally generated map.', '由 Ondřej Žára（ondras）制作，为 2017 年 7DRL 作品，源码以 ISC 许可在 GitHub 发布。原页托管在 ondras.github.io/sleeping-beauty，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Ondřej Žára (ondras) for 7DRL 2017; the source is ISC-licensed on GitHub. Hosted at ondras.github.io/sleeping-beauty; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/sleeping-beauty.jpg', 1280, 800, 'center', '["assets/posters/sleeping-beauty.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -14, 1794794400000, 'Enter the briar tower and try to wake the princess.', '', '', 1);
